<?php
declare(strict_types=1);

require dirname(__DIR__) . '/app/bootstrap.php';
$user = require_role('admin');
$stats = db()->query("SELECT (SELECT COUNT(*) FROM users WHERE role='client') clients, (SELECT COUNT(*) FROM users WHERE role='provider') providers, (SELECT COUNT(*) FROM provider_profiles WHERE verification_status='pending') pending_providers, (SELECT COUNT(*) FROM service_requests WHERE status='open') open_requests, (SELECT COUNT(*) FROM reviews WHERE status='pending') pending_reviews")->fetch();
$recentUsers = db()->query("SELECT u.id,u.full_name,u.phone,u.role,u.status,u.created_at,pp.verification_status FROM users u LEFT JOIN provider_profiles pp ON pp.user_id=u.id ORDER BY u.created_at DESC LIMIT 8")->fetchAll();
$recentRequests = db()->query("SELECT r.id,r.title,r.status,r.created_at,c.name category_name,d.name district_name,u.full_name client_name FROM service_requests r JOIN categories c ON c.id=r.category_id JOIN districts d ON d.id=r.district_id JOIN users u ON u.id=r.client_id ORDER BY r.created_at DESC LIMIT 8")->fetchAll();
$pageTitle='Administración'; $pageSubtitle='Estado general del marketplace'; $activeDashboard='dashboard';
require dirname(__DIR__) . '/templates/dashboard-header.php';
?>
<div class="page-head"><div><h2>Resumen operativo</h2><p>Actividad real registrada en la plataforma.</p></div><div class="page-actions"><a class="btn btn-secondary" href="<?=e(url())?>">Ver sitio</a></div></div>
<div class="stats-grid"><div class="stat-card"><div class="stat-top"><span>Clientes</span><span class="stat-icon"><?=icon('user')?></span></div><strong><?=(int)$stats['clients']?></strong></div><div class="stat-card"><div class="stat-top"><span>Proveedores</span><span class="stat-icon"><?=icon('tools')?></span></div><strong><?=(int)$stats['providers']?></strong></div><div class="stat-card"><div class="stat-top"><span>Por validar</span><span class="stat-icon"><?=icon('shield')?></span></div><strong><?=(int)$stats['pending_providers']?></strong></div><div class="stat-card"><div class="stat-top"><span>Solicitudes abiertas</span><span class="stat-icon"><?=icon('briefcase')?></span></div><strong><?=(int)$stats['open_requests']?></strong></div></div>
<?php if((int)$stats['pending_providers']>0 || (int)$stats['pending_reviews']>0):?><div class="alert alert-warning">Tienes <?=(int)$stats['pending_providers']?> proveedor(es) y <?=(int)$stats['pending_reviews']?> reseña(s) pendientes de moderación.</div><?php endif;?>
<div class="panel-grid equal">
<section class="panel"><div class="panel-header"><h2>Usuarios recientes</h2><a class="btn btn-secondary btn-small" href="<?=e(url('admin/users.php'))?>">Ver todos</a></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Usuario</th><th>Rol</th><th>Estado</th></tr></thead><tbody><?php foreach($recentUsers as $row):?><tr><td class="table-title"><a href="<?=e(url('admin/user.php?id='.(int)$row['id']))?>"><strong><?=e($row['full_name'])?></strong></a><span><?=e(mask_phone($row['phone']))?></span></td><td><?=e(['client'=>'Cliente','provider'=>'Proveedor','admin'=>'Admin'][$row['role']])?></td><td><span class="status status-<?=e(status_class($row['role']==='provider'?($row['verification_status']??'pending'):$row['status']))?>"><?=e(status_label($row['role']==='provider'?($row['verification_status']??'pending'):$row['status']))?></span></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><div class="panel-header"><h2>Solicitudes recientes</h2><a class="btn btn-secondary btn-small" href="<?=e(url('admin/requests.php'))?>">Ver todas</a></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Solicitud</th><th>Estado</th></tr></thead><tbody><?php foreach($recentRequests as $row):?><tr><td class="table-title"><a href="<?=e(url('request-view.php?id='.(int)$row['id']))?>"><strong><?=e($row['title'])?></strong></a><span><?=e($row['category_name'])?> · <?=e($row['district_name'])?></span></td><td><span class="status status-<?=e(status_class($row['status']))?>"><?=e(status_label($row['status']))?></span></td></tr><?php endforeach;?></tbody></table></div></section>
